import data from './localities-data.js?v=9';
import {esc} from './core.js?v=9';
export const normalize=s=>String(s||'').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const translated={GRU:'São Paulo',CGH:'São Paulo',GIG:'Rio de Janeiro',SDU:'Rio de Janeiro',VCP:'Campinas',CNF:'Belo Horizonte',LIS:'Lisboa',LHR:'Londres',LGW:'Londres',LCY:'Londres',STN:'Londres',CDG:'Paris',ORY:'Paris',FCO:'Roma',CIA:'Roma',MXP:'Milão',LIN:'Milão',MAD:'Madri',JFK:'Nova York',LGA:'Nova York',EWR:'Nova York',HND:'Tóquio',NRT:'Tóquio',MEX:'Cidade do México',PTY:'Cidade do Panamá',CPT:'Cidade do Cabo',JNB:'Joanesburgo',PEK:'Pequim',PKX:'Pequim',ZRH:'Zurique',VIE:'Viena',BRU:'Bruxelas',ATH:'Atenas',CPH:'Copenhague',ARN:'Estocolmo',ICN:'Seul',GMP:'Seul',MUC:'Munique',PRG:'Praga',WAW:'Varsóvia',BER:'Berlim',EZE:'Buenos Aires',AEP:'Buenos Aires'};
const preferred=['GRU','GIG','CNF','LIS','LHR','CDG','FCO','MXP','JFK','HND','MEX','PTY','CPT','JNB','PEK','ICN','EZE'];
const names=new Intl.DisplayNames(['pt-BR'],{type:'region'}),groups=new Map(),byCode=new Map();
for(const [code,original,country,region,airport,large] of data){const city=translated[code]||original,key=normalize(city)+'|'+country;const item={code,city,country,region,airport,large,original};byCode.set(code,item);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item);}
export const places=[...groups.values()].map(items=>{items.sort((a,b)=>(preferred.includes(b.code)?100:b.large?10:0)-(preferred.includes(a.code)?100:a.large?10:0)||a.code.localeCompare(b.code));const p={...items[0],codes:items.map(i=>i.code)};p.label=`${p.city}${p.country==='BR'?', '+p.region:''} · ${names.of(p.country)}`;p.search=normalize([p.label,...items.map(i=>i.original)].join(' '));for(const i of items)byCode.set(i.code,{...i,place:p});return p;}).sort((a,b)=>a.label.localeCompare(b.label,'pt-BR'));
export function placeForAirport(code){return byCode.get(code)?.place||null;}
export function airportName(code){const item=byCode.get(code);return item?`${translated[code]||item.city} · ${item.airport} (${code})`:code;}
export function resolvePlace(value){const n=normalize(value);if(!n)return null;const code=byCode.get(String(value).trim().toUpperCase());if(code)return code.place;const exact=places.filter(p=>normalize(p.label)===n);if(exact.length===1)return exact[0];const sameCity=places.filter(p=>normalize(p.city)===n||normalize(p.original)===n);if(sameCity.length===1)return sameCity[0];return null;}
export function suggestPlaces(value){const n=normalize(value);if(!n)return ['GRU','GIG','BSB','LIS','CDG','MIA'].map(placeForAirport).filter(Boolean);return places.filter(p=>normalize(p.city).startsWith(n)||p.search.includes(n)).sort((a,b)=>(a.country==='BR'?-1:0)-(b.country==='BR'?-1:0)||a.city.length-b.city.length).slice(0,10);}
export function localityInput(id,name,code='',placeholder='Digite uma cidade'){const label=placeForAirport(code)?.label||code;return `<input id="${id}" name="${name}" data-locality list="${id}-places" value="${esc(label)}" placeholder="${esc(placeholder)}" autocomplete="off" required><datalist id="${id}-places">${suggestPlaces(label).map(p=>`<option value="${esc(p.label)}"></option>`).join('')}</datalist>`;}
if(typeof document!=='undefined')document.addEventListener('input',e=>{const input=e.target;if(!input.matches('[data-locality]'))return;const list=document.getElementById(input.getAttribute('list'));if(list)list.innerHTML=suggestPlaces(input.value).map(p=>`<option value="${esc(p.label)}"></option>`).join('');input.setCustomValidity('');});
